  1297  static int bcf_dec_size_safe(uint8_t *p, uint8_t *end, uint8_t **q,
  1298                               int *num, int *type) {
  1299      int r;
  1300      if (p >= end) return -1;
  1301      *type = *p & 0xf;
  1302      if (*p>>4 != 15) {
  1303          *q = p + 1;
  1304          *num = *p >> 4;
  1305          return 0;
  1306      }
  1307      r = bcf_dec_typed_int1_safe(p + 1, end, q, num);
  1308      if (r) return r;
  1309      return *num >= 0 ? 0 : -1;
  1310  }
