  1417                                  || id_tmp[key].key == NULL))) {
  1418              if (!reports++ || hts_verbose >= HTS_LOG_DEBUG)
  1419                  hts_log_warning("Bad BCF record at %s:%"PRIhts_pos": Invalid %s id %d", bcf_seqname_safe(hdr,rec), rec->pos+1, "INFO", key);
