  1320  #define bcf_int16_vector_end (-32767)       /* INT16_MIN + 1 */
  1321  #define bcf_int32_vector_end (-2147483647)  /* INT32_MIN + 1 */
  1322  #define bcf_int64_vector_end (-9223372036854775807LL)  /* INT64_MIN + 1 */
