  1363  static inline int bcf_format_gt(bcf_fmt_t *fmt, int isample, kstring_t *str)
  1364  {
  1365      uint32_t e = 0;
  1366      #define BRANCH(type_t, missing, vector_end) { \
  1367          type_t *ptr = (type_t*) (fmt->p + isample*fmt->size); \
  1368          int i; \
  1369          for (i=0; i<fmt->n && ptr[i]!=vector_end; i++) \
  1370          { \
  1371              if ( i ) e |= kputc("/|"[ptr[i]&1], str) < 0; \
  1372              if ( !(ptr[i]>>1) ) e |= kputc('.', str) < 0; \
  1373              else e |= kputw((ptr[i]>>1) - 1, str) < 0; \
  1374          } \
  1375          if (i == 0) e |= kputc('.', str) < 0; \
  1376      }
  1377      switch (fmt->type) {
  1378          case BCF_BT_INT8:  BRANCH(int8_t,  bcf_int8_missing, bcf_int8_vector_end); break;
  1379          case BCF_BT_INT16: BRANCH(int16_t, bcf_int16_missing, bcf_int16_vector_end); break;
  1380          case BCF_BT_INT32: BRANCH(int32_t, bcf_int32_missing, bcf_int32_vector_end); break;
  1381          case BCF_BT_NULL:  e |= kputc('.', str) < 0; break;
  1382          default: hts_log_error("Unexpected type %d", fmt->type); return -2;
  1383      }
  1384      #undef BRANCH
  1385      return e == 0 ? 0 : -1;
  1386  }
