   240  // Parse tab-delimited text, filling in a string of column types and returning
   241  // the number of columns spotted (within [u,ulim), and up to column_len) or -1
   242  // if non-printable characters were seen.  Column types:
   243  //     i: integer, s: strand sign, C: CIGAR, O: SAM optional field, Z: anything
   244  static int
   245  parse_tabbed_text(char *columns, int column_len,
   246                    const unsigned char *u, const unsigned char *ulim,
   247                    int *complete)
   248  {
   249      const char *str  = (const char *) u;
   250      const char *slim = (const char *) ulim;
   251      const char *s;
   252      int ncolumns = 0;
   253
   254      enum { digit = 1, leading_sign = 2, cigar_operator = 4, other = 8 };
   255      unsigned seen = 0;
   256      *complete = 0;
   257
   258      for (s = str; s < slim; s++)
   259          if (*s >= ' ') {
   260              if (isdigit_c(*s))
   261                  seen |= digit;
   262              else if ((*s == '+' || *s == '-') && s == str)
   263                  seen |= leading_sign;
   264              else if (strchr(BAM_CIGAR_STR, *s) && s > str && isdigit_c(s[-1]))
   265                  seen |= cigar_operator;
   266              else
   267                  seen |= other;
   268          }
   269          else if (*s == '\t' || *s == '\r' || *s == '\n') {
   270              size_t len = s - str;
   271              char type;
   272
   273              if (seen == digit || seen == (leading_sign|digit)) type = 'i';
   274              else if (seen == (digit|cigar_operator)) type = 'C';
   275              else if (len == 1)
   276                  switch (str[0]) {
   277                  case '*': type = 'C'; break;
   278                  case '+': case '-': case '.': type = 's'; break;
   279                  default: type = 'Z'; break;
   280                  }
   281              else if (len >= 5 && str[2] == ':' && str[4] == ':') type = 'O';
   282              else type = 'Z';
   283
   284              columns[ncolumns++] = type;
   285              if (*s != '\t' || ncolumns >= column_len - 1) {
   286                  *complete = 1; // finished the line or more columns than needed
   287                  break;
   288              }
   289
   290              str = s + 1;
   291              seen = 0;
   292          }
   293          else return -1;
   294
   295      columns[ncolumns] = '\0';
   296      return ncolumns;
   297  }
