  2961      else if (strcasecmp(format, "bcf") == 0) strcpy(mode, "b");
  2962      else if (strcasecmp(format, "vcf") == 0) strcpy(mode, "");
  2963      else if (strcasecmp(format, "vcf.gz") == 0 || strcasecmp(format, "vcf.bgz") == 0) strcpy(mode, "z");
