  2977  static inline uint8_t *bcf_unpack_fmt_core1(uint8_t *ptr, int n_sample, bcf_fmt_t *fmt)
  2978  {
  2979      uint8_t *ptr_start = ptr;
  2980      fmt->id = bcf_dec_typed_int1(ptr, &ptr);
  2981      fmt->n = bcf_dec_size(ptr, &ptr, &fmt->type);
  2982      fmt->size = fmt->n << bcf_type_shift[fmt->type];
  2983      fmt->p = ptr;
  2984      fmt->p_off  = ptr - ptr_start;
  2985      fmt->p_free = 0;
  2986      ptr += n_sample * fmt->size;
  2987      fmt->p_len = ptr - fmt->p;
  2988      return ptr;
  2989  }
  2990
  2991  static inline uint8_t *bcf_unpack_info_core1(uint8_t *ptr, bcf_info_t *info)
  2992  {
  2993      uint8_t *ptr_start = ptr;
  2994      info->key = bcf_dec_typed_int1(ptr, &ptr);
  2995      info->len = bcf_dec_size(ptr, &ptr, &info->type);
  2996      info->vptr = ptr;
  2997      info->vptr_off  = ptr - ptr_start;
  2998      info->vptr_free = 0;
  2999      info->v1.i = 0;
  3000      if (info->len == 1) {
  3001          if (info->type == BCF_BT_INT8 || info->type == BCF_BT_CHAR) info->v1.i = *(int8_t*)ptr;
  3002          else if (info->type == BCF_BT_INT32) info->v1.i = le_to_i32(ptr);
  3003          else if (info->type == BCF_BT_FLOAT) info->v1.f = le_to_float(ptr);
  3004          else if (info->type == BCF_BT_INT16) info->v1.i = le_to_i16(ptr);
  3005          else if (info->type == BCF_BT_INT64) info->v1.i = le_to_i64(ptr);
  3006      }
  3007      ptr += info->len << bcf_type_shift[info->type];
  3008      info->vptr_len = ptr - info->vptr;
  3009      return ptr;
  3010  }
  3011
  3012  int bcf_unpack(bcf1_t *b, int which)
  3013  {
  3014      if ( !b->shared.l ) return 0; // Building a new BCF record from scratch
  3015      uint8_t *ptr = (uint8_t*)b->shared.s, *ptr_ori;
  3016      int i;
  3017      bcf_dec_t *d = &b->d;
  3018      if (which & BCF_UN_FLT) which |= BCF_UN_STR;
  3019      if (which & BCF_UN_INFO) which |= BCF_UN_SHR;
  3020      if ((which&BCF_UN_STR) && !(b->unpacked&BCF_UN_STR))
  3021      {
  3022          kstring_t tmp;
  3023
  3024          // ID
  3025          tmp.l = 0; tmp.s = d->id; tmp.m = d->m_id;
  3026          ptr_ori = ptr;
  3027          ptr = bcf_fmt_sized_array(&tmp, ptr);
  3028          b->unpack_size[0] = ptr - ptr_ori;
  3029          kputc('\0', &tmp);
  3030          d->id = tmp.s; d->m_id = tmp.m;
  3031
  3032          // REF and ALT are in a single block (d->als) and d->alleles are pointers into this block
  3033          hts_expand(char*, b->n_allele, d->m_allele, d->allele); // NM: hts_expand() is a macro
  3034          tmp.l = 0; tmp.s = d->als; tmp.m = d->m_als;
  3035          ptr_ori = ptr;
  3036          for (i = 0; i < b->n_allele; ++i) {
  3037              // Use offset within tmp.s as realloc may change pointer
  3038              d->allele[i] = (char *)(intptr_t)tmp.l;
  3039              ptr = bcf_fmt_sized_array(&tmp, ptr);
  3040              kputc('\0', &tmp);
  3041          }
  3042          b->unpack_size[1] = ptr - ptr_ori;
  3043          d->als = tmp.s; d->m_als = tmp.m;
  3044
  3045          // Convert our offsets within tmp.s back to pointers again
  3046          for (i = 0; i < b->n_allele; ++i)
  3047              d->allele[i] = d->als + (ptrdiff_t)d->allele[i];
  3048          b->unpacked |= BCF_UN_STR;
  3049      }
  3050      if ((which&BCF_UN_FLT) && !(b->unpacked&BCF_UN_FLT)) { // FILTER
  3051          ptr = (uint8_t*)b->shared.s + b->unpack_size[0] + b->unpack_size[1];
  3052          ptr_ori = ptr;
  3053          if (*ptr>>4) {
  3054              int type;
  3055              d->n_flt = bcf_dec_size(ptr, &ptr, &type);
  3056              hts_expand(int, d->n_flt, d->m_flt, d->flt);
  3057              for (i = 0; i < d->n_flt; ++i)
  3058                  d->flt[i] = bcf_dec_int1(ptr, type, &ptr);
  3059          } else ++ptr, d->n_flt = 0;
  3060          b->unpack_size[2] = ptr - ptr_ori;
  3061          b->unpacked |= BCF_UN_FLT;
  3062      }
  3063      if ((which&BCF_UN_INFO) && !(b->unpacked&BCF_UN_INFO)) { // INFO
  3064          ptr = (uint8_t*)b->shared.s + b->unpack_size[0] + b->unpack_size[1] + b->unpack_size[2];
  3065          hts_expand(bcf_info_t, b->n_info, d->m_info, d->info);
  3066          for (i = 0; i < d->m_info; ++i) d->info[i].vptr_free = 0;
  3067          for (i = 0; i < b->n_info; ++i)
  3068              ptr = bcf_unpack_info_core1(ptr, &d->info[i]);
  3069          b->unpacked |= BCF_UN_INFO;
  3070      }
  3071      if ((which&BCF_UN_FMT) && b->n_sample && !(b->unpacked&BCF_UN_FMT)) { // FORMAT
  3072          ptr = (uint8_t*)b->indiv.s;
  3073          hts_expand(bcf_fmt_t, b->n_fmt, d->m_fmt, d->fmt);
  3074          for (i = 0; i < d->m_fmt; ++i) d->fmt[i].p_free = 0;
  3075          for (i = 0; i < b->n_fmt; ++i)
  3075          for (i = 0; i < b->n_fmt; ++i)
  3076              ptr = bcf_unpack_fmt_core1(ptr, b->n_sample, &d->fmt[i]);
  3077          b->unpacked |= BCF_UN_FMT;
  3078      }
  3079      return 0;
  3080  }
  3081
  3082  int vcf_format(const bcf_hdr_t *h, const bcf1_t *v, kstring_t *s)
  3083  {
  3084      int i;
  3085      int32_t max_dt_id = h->n[BCF_DT_ID];
  3086      const char *chrom = bcf_seqname(h, v);
  3087      if (!chrom) {
  3088          hts_log_error("Invalid BCF, CONTIG id=%d not present in the header",
  3089                        v->rid);
  3090          errno = EINVAL;
  3091          return -1;
  3092      }
  3093      bcf_unpack((bcf1_t*)v, BCF_UN_ALL);
  3094      kputs(chrom, s); // CHROM
  3095      kputc('\t', s); kputll(v->pos + 1, s); // POS
  3096      kputc('\t', s); kputs(v->d.id ? v->d.id : ".", s); // ID
  3097      kputc('\t', s); // REF
  3098      if (v->n_allele > 0) kputs(v->d.allele[0], s);
  3099      else kputc('.', s);
  3100      kputc('\t', s); // ALT
  3101      if (v->n_allele > 1) {
  3102          for (i = 1; i < v->n_allele; ++i) {
  3103              if (i > 1) kputc(',', s);
  3104              kputs(v->d.allele[i], s);
  3105          }
  3106      } else kputc('.', s);
  3107      kputc('\t', s); // QUAL
  3108      if ( bcf_float_is_missing(v->qual) ) kputc('.', s); // QUAL
  3109      else kputd(v->qual, s);
  3110      kputc('\t', s); // FILTER
  3111      if (v->d.n_flt) {
  3112          for (i = 0; i < v->d.n_flt; ++i) {
  3113              int32_t idx = v->d.flt[i];
  3114              if (idx < 0 || idx >= max_dt_id
  3115                  || h->id[BCF_DT_ID][idx].key == NULL) {
  3116                  hts_log_error("Invalid BCF, the FILTER tag id=%d at %s:%"PRIhts_pos" not present in the header",
  3117                                idx, bcf_seqname_safe(h, v), v->pos + 1);
  3118                  errno = EINVAL;
  3119                  return -1;
  3120              }
  3121              if (i) kputc(';', s);
  3122              kputs(h->id[BCF_DT_ID][idx].key, s);
  3123          }
  3124      } else kputc('.', s);
  3125      kputc('\t', s); // INFO
  3126      if (v->n_info) {
  3127          int first = 1;
  3128          for (i = 0; i < v->n_info; ++i) {
  3129              bcf_info_t *z = &v->d.info[i];
  3130              if ( !z->vptr ) continue;
  3131              if ( !first ) kputc(';', s);
  3132              first = 0;
  3133              if (z->key < 0 || z->key >= max_dt_id
  3134                  || h->id[BCF_DT_ID][z->key].key == NULL) {
  3135                  hts_log_error("Invalid BCF, the INFO tag id=%d is %s at %s:%"PRIhts_pos,
  3136                                z->key,
  3137                                z->key < 0 ? "negative"
  3138                                : (z->key >= max_dt_id ? "too large" : "not present in the header"),
  3139                                bcf_seqname_safe(h, v), v->pos+1);
  3140                  errno = EINVAL;
  3141                  return -1;
  3142              }
  3143              kputs(h->id[BCF_DT_ID][z->key].key, s);
  3144              if (z->len <= 0) continue;
  3145              kputc('=', s);
  3146              if (z->len == 1)
  3147              {
  3148                  switch (z->type)
  3149                  {
  3150                      case BCF_BT_INT8:  if ( z->v1.i==bcf_int8_missing ) kputc('.', s); else kputw(z->v1.i, s); break;
  3151                      case BCF_BT_INT16: if ( z->v1.i==bcf_int16_missing ) kputc('.', s); else kputw(z->v1.i, s); break;
  3152                      case BCF_BT_INT32: if ( z->v1.i==bcf_int32_missing ) kputc('.', s); else kputw(z->v1.i, s); break;
  3153                      case BCF_BT_INT64: if ( z->v1.i==bcf_int64_missing ) kputc('.', s); else kputll(z->v1.i, s); break;
  3154                      case BCF_BT_FLOAT: if ( bcf_float_is_missing(z->v1.f) ) kputc('.', s); else kputd(z->v1.f, s); break;
  3155                      case BCF_BT_CHAR:  kputc(z->v1.i, s); break;
  3156                      default:
  3157                          hts_log_error("Unexpected type %d at %s:%"PRIhts_pos, z->type, bcf_seqname_safe(h, v), v->pos+1);
  3158                          errno = EINVAL;
  3159                          return -1;
  3160                  }
  3161              }
  3162              else bcf_fmt_array(s, z->len, z->type, z->vptr);
  3163          }
  3164          if ( first ) kputc('.', s);
  3165      } else kputc('.', s);
  3166      // FORMAT and individual information
  3167      if (v->n_sample)
  3168      {
  3169          int i,j;
  3170          if ( v->n_fmt)
  3171          {
  3172              int gt_i = -1;
  3173              bcf_fmt_t *fmt = v->d.fmt;
  3174              int first = 1;
  3175              for (i = 0; i < (int)v->n_fmt; ++i) {
  3176                  if ( !fmt[i].p ) continue;
  3177                  kputc(!first ? ':' : '\t', s); first = 0;
  3178                  if (fmt[i].id < 0 || fmt[i].id >= max_dt_id
  3179                      || h->id[BCF_DT_ID][fmt[i].id].key == NULL) //!bcf_hdr_idinfo_exists(h,BCF_HL_FMT,fmt[i].id) )
  3180                  {
  3181                      hts_log_error("Invalid BCF, the FORMAT tag id=%d at %s:%"PRIhts_pos" not present in the header", fmt[i].id, bcf_seqname_safe(h, v), v->pos+1);
  3182                      errno = EINVAL;
  3183                      return -1;
  3184                  }
  3185                  kputs(h->id[BCF_DT_ID][fmt[i].id].key, s);
  3186                  if (strcmp(h->id[BCF_DT_ID][fmt[i].id].key, "GT") == 0) gt_i = i;
  3187              }
  3188              if ( first ) kputs("\t.", s);
  3189              for (j = 0; j < v->n_sample; ++j) {
  3190                  kputc('\t', s);
  3191                  first = 1;
  3192                  for (i = 0; i < (int)v->n_fmt; ++i) {
  3193                      bcf_fmt_t *f = &fmt[i];
  3194                      if ( !f->p ) continue;
  3195                      if (!first) kputc(':', s);
  3196                      first = 0;
  3197                      if (gt_i == i)
  3198                          bcf_format_gt(f,j,s);
  3199                      else
  3200                          bcf_fmt_array(s, f->n, f->type, f->p + j * (size_t)f->size);
  3201                  }
  3202                  if ( first ) kputc('.', s);
  3203              }
  3204          }
  3205          else
  3206              for (j=0; j<=v->n_sample; j++)
  3207                  kputs("\t.", s);
  3208      }
  3209      kputc('\n', s);
  3210      return 0;
  3211  }
